mapper.select:
select
con.Con_Name as conName, mn.Id as id, mn.Pay_Id as payId, mn.Con_Id as conId, mn.P_Id as pId, mn.Mip_Is_Con as mipIsCon, mn.Mip_Con_Id as mipConId, mn.State as state, mn.State_Time as stateTime, mn.Create_Uid as createUid, u.U_Name as createUname, mn.Create_Time as createTime, mn.Mip_Construction_Unit as mipConstructionUnit, mn.Mip_Source_Funds as mipSourceFunds, mn.Mip_Investment_Last as mipInvestmentLast, mn.Mip_Approve_Loan as mipApproveLoan, mn.Mip_Cumulative_Release as mipCumulativeRelease, mn.Mip_Con_Money as mipConMoney, mn.Mip_Consignee as mipConsignee, mn.Mip_Bank as mipBank, mn.Mip_Account_Number as mipAccountNumber, mn.Mip_Applied_Amount as mipAppliedAmount, mn.Mip_Progress_Funds as mipProgressFunds, mn.Mip_Investment_Total as mipInvestmentTotal, mn.Mip_Code as mipCode, pay.pay_Type as markType, pay.pay_Type as payType, pay.pay_Application_Date as payApplicationDate, pay.pay_Create_Uid as payCreateUid, pay.pay_Create_Uname as payCreateUname from Market_Investment_Payment mn
left join Con_Contract con on con.Con_Id=mn.Con_Id left join SYS_User u on mn.Create_Uid=u.U_ID left join con_pay pay on pay.pay_id = mn.pay_id
and mn.P_Id = #{params.pId}
and mn.Con_Id = #{params.conId}
and con.Con_Name like concat('%',#{params.conName},'%')
and likePname(#{params.pName},pro.P_Id)=true
and INSTR(pro.P_Name,#{params.pName})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc
limit #{params.start},#{params.size}
